<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · LiftCard</h1>
      <p class="demo-page__lead">
        来自 video-code 的「立体卡片展示」：鼠标移上去时，底层那块渐变底板先绕 X 轴仰起 35°、抬高并加深阴影，
        前景照片顺着 <code>translateZ</code> 往观众方向弹出 120px、放大一点、往上挪；底板后面还会浮出一张
        模糊过的倒影图增加层次。两条缓动曲线不一样，所以会有「弹一下再落定」的手感。
      </p>
    </header>

    <section class="lift-demo">
      <div class="lift-demo__head">
        <h2 class="demo-page__section-title">把指针移上去</h2>
        <code class="lift-demo__tag">hover · 3D</code>
      </div>
      <p class="demo-card__text">
        左边是原尺寸（420×420），中间强制展开（<code>:active="true"</code>，不依赖 hover，适合移动端或截图），
        右边换了一套配色和更小的圆角。三张都是同一套 3D 关系，只是参数不同。
      </p>

      <div class="lift-demo__row">
        <div class="lift-demo__cell">
          <div class="lift-demo__box">
            <LiftCard
              :image="images[0]"
              :width="320"
              :height="320"
              title="立体展示卡"
              subtitle="左侧 / 悬停触发展开"
            />
          </div>
          <p>hover 展开（<code>tilt 35</code> / <code>liftZ 120</code>）</p>
        </div>
        <div class="lift-demo__cell">
          <div class="lift-demo__box is-open">
            <LiftCard
              :image="images[1]"
              :width="320"
              :height="320"
              :active="true"
              title="强制展开"
              subtitle="active 属性控制"
            />
          </div>
          <p>强制展开（<code>:active="true"</code>）</p>
        </div>
        <div class="lift-demo__cell">
          <div class="lift-demo__box is-dark">
            <LiftCard
              :image="images[2]"
              :width="320"
              :height="320"
              :tilt="28"
              :lift-z="90"
              :radius="6"
              from="#0f766e"
              to="#115e59"
              title="换配色 / 小圆角"
              subtitle="tilt 28 · liftZ 90 · radius 6"
            />
          </div>
          <p>另一种参数（<code>from</code> / <code>to</code> / <code>radius</code>）</p>
        </div>
      </div>

      <div class="lift-demo__stage">
        <div class="lift-demo__tools">
          <input
            ref="imageInput"
            class="lift-demo__file"
            type="file"
            accept="image/*"
            aria-label="上传替换卡片图片"
            @change="replaceImage"
          />
          <button class="lift-demo__upload" type="button" @click="imageInput?.click()">
            <span aria-hidden="true">↥</span> 上传图片替换
          </button>
          <button
            v-if="uploadedImage"
            class="lift-demo__reset"
            type="button"
            @click="resetImage"
          >
            恢复示例图
          </button>
          <span class="lift-demo__tip">支持 JPG、PNG、WebP</span>
        </div>
        <LiftCard
          :image="images[3]"
          :width="420"
          :height="420"
          :tilt="35"
          :lift-z="120"
          :hover-lift="15"
          title="立体卡片展示"
          subtitle="底板仰起 35° · 照片弹出 120px · 倒影浮现"
        />
      </div>

      <p class="lift-demo__hint">
        提示：卡片外圈就是 hover 判定区，指针进去后底板仰起、照片浮起，移出自动落回。
      </p>
    </section>

    <DemoPreview class="lift-preview">
      <LevaPlayground
        name="LiftCard"
        :component="LiftCard"
        :schema="LiftCardSchema"
        :presets="{ image: images[0], title: '立体卡片', subtitle: 'hover 试试', active: true }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>width</code> / <code>height</code> 是卡片尺寸，<code>tilt</code> 是底板仰角，
        <code>liftZ</code> 是照片往外的弹出距离，<code>hoverLift</code> 是整张卡抬起的距离，
        <code>scale</code> 以图片中心为原点调整画面缩放，<code>radius</code> 是圆角，<code>from</code> / <code>to</code> 是底板渐变两端，
        <code>reflection</code> 控制底板后面的模糊倒影，<code>title</code> / <code>subtitle</code>
        是压在图下方的文字，<code>active</code> 可以在不 hover 的情况下强制展开。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'
import sampleImage from '../assets/lift-card-cat.png'
import LiftCardSchema from '@melt-js/comps-vue3/src/components/LiftCard.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const LiftCard = remoteComponent('LiftCard')

const images = ref([sampleImage, sampleImage, sampleImage, sampleImage])
const imageInput = ref<HTMLInputElement>()
const uploadedImage = ref('')

function replaceImage(event: Event) {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file || !file.type.startsWith('image/')) return

  if (uploadedImage.value) URL.revokeObjectURL(uploadedImage.value)
  uploadedImage.value = URL.createObjectURL(file)
  images.value = images.value.map(() => uploadedImage.value)
  input.value = ''
}

function resetImage() {
  if (uploadedImage.value) URL.revokeObjectURL(uploadedImage.value)
  uploadedImage.value = ''
  images.value = images.value.map(() => sampleImage)
}

onBeforeUnmount(() => {
  if (uploadedImage.value) URL.revokeObjectURL(uploadedImage.value)
})

const stageStyle = {
  display: 'grid',
  placeItems: 'center',
  height: '560px',
  padding: '32px',
  background: '#f0f2f5',
}
</script>

